CREATE OR REPLACE FUNCTION public.ar_apply_moderation(p_user_id uuid, p_source_type text, p_source_id uuid, p_content text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  result jsonb := public.ar_find_profanity(p_content);
  v_count integer := coalesce((result->>'count')::integer,0);
  v_matches text[] := array(select jsonb_array_elements_text(coalesce(result->'matches','[]'::jsonb)));
  old_recent integer := 0;
  old_window timestamptz;
  new_recent integer;
  new_total integer;
  v_color text;
  v_auto_report boolean := false;
begin
  if v_count <= 0 or p_user_id is null then return jsonb_build_object('count',0,'matches','[]'::jsonb,'flag',null); end if;
  select offense_count,recent_offense_count,recent_window_start into new_total,old_recent,old_window from public.user_moderation where user_id=p_user_id;
  if old_window is null or old_window < now()-interval '24 hours' then
    new_recent := v_count;
    old_window := now();
  else
    new_recent := old_recent + v_count;
  end if;
  new_total := coalesce(new_total,0) + v_count;
  v_color := case when new_recent >= 3 then 'red' else 'yellow' end;
  v_auto_report := new_total > 20 and not exists(select 1 from public.moderation_reports r where r.user_id=p_user_id and r.reason='Automatic profanity report: more than 20 flagged uses.');
  insert into public.user_moderation(user_id,offense_count,recent_offense_count,recent_window_start,flag_color,flagged_until,auto_reported_at,updated_at)
  values(p_user_id,new_total,new_recent,old_window,v_color,now()+interval '24 hours',case when v_auto_report then now() else null end,now())
  on conflict(user_id) do update set offense_count=excluded.offense_count,recent_offense_count=excluded.recent_offense_count,recent_window_start=excluded.recent_window_start,flag_color=excluded.flag_color,flagged_until=excluded.flagged_until,auto_reported_at=coalesce(public.user_moderation.auto_reported_at,excluded.auto_reported_at),updated_at=now();
  if v_auto_report then
    insert into public.moderation_reports(user_id,source_type,source_id,reason,offense_count) values(p_user_id,p_source_type,p_source_id,'Automatic profanity report: more than 20 flagged uses.',new_total);
  end if;
  return jsonb_build_object('count',v_count,'matches',to_jsonb(v_matches),'flag',v_color,'flagged_until',now()+interval '24 hours','auto_reported',v_auto_report,'offense_count',new_total);
end;
$function$

CREATE OR REPLACE FUNCTION public.ar_find_profanity(p_content text)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  normalized text := regexp_replace(lower(coalesce(p_content,'')), '[^a-z0-9]+', ' ', 'g');
  terms text[] := array[
    'fuck','fucking','fucker','fuckhead','fuckface','shit','shitting','shitter','shithead','bitch','bitches','bitchass','bastard','asshole','dick','dickhead','pussy','cunt','slut','whore','motherfucker','cock','cocksucker','douchebag','prick','twat','wanker','dipshit','jackass','bullshit','dumbass','nigger','faggot','retard','crap','piss','hoe','arsehole','bugger','clit','cockhead','goddamn','motherfuckers','bastards','dumbfuck','asswipe','cumslut','jizz','slutty','blowjob',
    'chutiya','chutiye','madarchod','maderchod','behenchod','bhenchod','bhosdike','bhosdi','gaand','gandu','randi','raand','harami','kutta','kuttiya','saala','saale','kamina','kamine','lauda','loda','chut','jhant','suar','bhosda','gandmasti','laund','laundiya','bakchod','bakchodi','hijra','chutiyapa','mc','bc','bsdk','bhosadike','harambhor','kamini','chutian','gaanddu','madarchodh','bhosdika','lodu','chutiyap','randiwe','haramzada','haramzadi','gandoo','jhantu','bhosada','randiya','saali','bhenkeode','chutmarani','gaandfat','gaandmora','kutti','chuth','tattu','chodna',
    'kanjar','kanjra','khasma','khasmakhania','fittehmu','fittehmoo','dalle','dalla','pentechoda','chawal','kuttapan','pencho','penchod',
    'aaizavli','aaizavadya','zavli','zavadya','bhadva','bhadvya','bullya','yedzhava','yedzhavya','gandit','chutya','lavda',
    'bokachoda','khanki','bal','khankirmag','chudmarani','gandmarani','magirchele','chodna','pod','podmarani','chodis','shor',
    'pundai','otha','ootha','pundamavane','thevadiya','thevadiyamavan','sunni','poolu','koothi','mayiru','munda','somberi','lucu','loosie','punda',
    'dhengey','dengey','lanja','lanjakodaka','pooku','puku','modda','gudha','sanka','lanjamunda','modagudhu','munde','maddalo',
    'soole','soolemaga','kullamari','munde','bolli','bollimaga',
    'myre','myru','patti','thendi','pooran','poori','vadamavane','pulayadi',
    'chutiyam','suvar','ghando','luppad'
  ];
  found text[] := '{}'; term text; n integer; occurrences integer := 0;
begin
  foreach term in array terms loop
    select count(*)::integer into n from regexp_matches(normalized, '(^| )' || term || '( |$)', 'g');
    if n > 0 then
      found := array_append(found, term);
      occurrences := occurrences + n;
    end if;
  end loop;
  return jsonb_build_object('count',occurrences,'matches',to_jsonb(found));
end;
$function$

CREATE OR REPLACE FUNCTION public.ar_moderate_comment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare r jsonb;
begin
  if new.user_id is not null and exists(select 1 from public.user_moderation where user_id=new.user_id and comment_banned_until is not null and comment_banned_until > now()) then
    raise exception 'You are temporarily banned from comments.' using errcode='42501';
  end if;
  r:=public.ar_apply_moderation(new.user_id,'comment',new.id,new.content);
  new.moderation_count:=coalesce((r->>'count')::integer,0);
  new.moderation_flag:=r->>'flag';
  new.moderation_matches:=array(select jsonb_array_elements_text(coalesce(r->'matches','[]'::jsonb)));
  return new;
end; $function$

