CREATE OR REPLACE FUNCTION public.delete_chapter_page(p_page_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_chapter_id uuid;
  v_page_count bigint;
  v_temporary_base bigint;
begin
  if not private.is_admin() then
    raise exception 'Admin access required';
  end if;
  if p_page_id is null then
    raise exception 'Page ID is required';
  end if;

  select page.chapter_id
  into v_chapter_id
  from public.chapter_pages page
  where page.id = p_page_id;

  if v_chapter_id is null then
    raise exception 'Page not found';
  end if;

  perform 1
  from public.chapter_pages page
  where page.chapter_id = v_chapter_id
  order by page.page_number, page.id
  for update;

  delete from public.chapter_pages
  where id = p_page_id;

  select count(*)
  into v_page_count
  from public.chapter_pages page
  where page.chapter_id = v_chapter_id;

  if v_page_count = 0 then
    return;
  end if;

  select coalesce(max(page.page_number), 0) + v_page_count + 1
  into v_temporary_base
  from public.chapter_pages page
  where page.chapter_id = v_chapter_id;

  with renumbered as (
    select page.id,
           row_number() over (order by page.page_number, page.id)::bigint as new_number
    from public.chapter_pages page
    where page.chapter_id = v_chapter_id
  )
  update public.chapter_pages page
  set page_number = v_temporary_base + renumbered.new_number
  from renumbered
  where page.id = renumbered.id;

  with renumbered as (
    select page.id,
           row_number() over (order by page.page_number, page.id)::bigint as new_number
    from public.chapter_pages page
    where page.chapter_id = v_chapter_id
  )
  update public.chapter_pages page
  set page_number = renumbered.new_number
  from renumbered
  where page.id = renumbered.id;
end;
$function$

CREATE OR REPLACE FUNCTION public.get_admin_analytics(p_days integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_now timestamptz := now();
  v_cutoff timestamptz;
  v_previous_start timestamptz;
  v_result jsonb;
begin
  if v_uid is null or not exists (select 1 from public.admins where user_id = v_uid) then
    raise exception 'Admin access required';
  end if;

  if p_days is not null and p_days not in (1, 7, 30, 90) then
    raise exception 'Analytics period must be 1, 7, 30, 90, or null';
  end if;

  v_cutoff := case when p_days is null then null else v_now - make_interval(days => p_days) end;
  v_previous_start := case when p_days is null then null else v_cutoff - make_interval(days => p_days) end;

  select jsonb_build_object(
    'total_views', (select count(*) from public.chapter_views),
    'total_likes', (select count(*) from public.chapter_likes) + (select count(*) from public.comment_likes),
    'total_shares', (select count(*) from public.chapter_shares),
    'total_ratings', (select count(*) from public.chapter_ratings),
    'total_comments', (select count(*) from public.comments),

    'current_views', case when p_days is null then (select count(*) from public.chapter_views)
      else (select count(*) from public.chapter_views where created_at >= v_cutoff and created_at <= v_now) end,
    'previous_views', case when p_days is null then 0
      else (select count(*) from public.chapter_views where created_at >= v_previous_start and created_at < v_cutoff) end,

    'current_likes', case when p_days is null then (select count(*) from public.chapter_likes) + (select count(*) from public.comment_likes)
      else (select count(*) from public.chapter_likes where created_at >= v_cutoff and created_at <= v_now)
        + (select count(*) from public.comment_likes where created_at >= v_cutoff and created_at <= v_now) end,
    'previous_likes', case when p_days is null then 0
      else (select count(*) from public.chapter_likes where created_at >= v_previous_start and created_at < v_cutoff)
        + (select count(*) from public.comment_likes where created_at >= v_previous_start and created_at < v_cutoff) end,

    'current_shares', case when p_days is null then (select count(*) from public.chapter_shares)
      else (select count(*) from public.chapter_shares where created_at >= v_cutoff and created_at <= v_now) end,
    'previous_shares', case when p_days is null then 0
      else (select count(*) from public.chapter_shares where created_at >= v_previous_start and created_at < v_cutoff) end,

    'current_comments', case when p_days is null then (select count(*) from public.comments)
      else (select count(*) from public.comments where created_at >= v_cutoff and created_at <= v_now) end,
    'previous_comments', case when p_days is null then 0
      else (select count(*) from public.comments where created_at >= v_previous_start and created_at < v_cutoff) end,

    'current_ratings', case when p_days is null then (select count(*) from public.chapter_ratings)
      else (select count(*) from public.chapter_ratings where created_at >= v_cutoff and created_at <= v_now) end,
    'previous_ratings', case when p_days is null then 0
      else (select count(*) from public.chapter_ratings where created_at >= v_previous_start and created_at < v_cutoff) end,

    'rating_sum', coalesce((select sum(rating) from public.chapter_ratings), 0),
    'rating_counts', coalesce((
      select jsonb_agg(jsonb_build_object('rating', x.rating, 'count', x.cnt) order by x.rating desc)
      from (select r.rating, count(*) as cnt from public.chapter_ratings r group by r.rating) x
    ), '[]'::jsonb),

    'released', case
      when p_days is null then (
        select count(*) from public.chapters c
        where lower(coalesce(c.status,'')) = 'published'
          and c.deleted_at is null
          and coalesce(c.release_date, c.created_at) <= v_now
      )
      else (
        select count(*) from public.chapters c
        where lower(coalesce(c.status,'')) = 'published'
          and c.deleted_at is null
          and coalesce(c.release_date, c.created_at) >= v_cutoff
          and coalesce(c.release_date, c.created_at) <= v_now
      )
    end,

    'bookmarks', (select count(*) from public.bookmarks),

    'active_readers', (
      select count(distinct viewer_key)
      from public.chapter_views
      where viewer_key is not null
        and created_at >= v_now - interval '30 days'
        and created_at <= v_now
    ),
    'returning_readers', (
      select count(*)
      from (
        select viewer_key
        from public.chapter_views
        where viewer_key is not null
          and created_at >= v_now - interval '30 days'
          and created_at <= v_now
        group by viewer_key
        having count(distinct ((created_at at time zone 'Asia/Kolkata')::date)) >= 2
      ) returning_users
    ),

    'period_active_readers', case when p_days is null then (
      select count(distinct viewer_key)
      from public.chapter_views
      where viewer_key is not null
        and created_at <= v_now
    ) else (
      select count(distinct viewer_key)
      from public.chapter_views
      where viewer_key is not null
        and created_at >= v_cutoff
        and created_at <= v_now
    ) end,

    'period_returning_readers', case when p_days is null then (
      select count(*)
      from (
        select viewer_key
        from public.chapter_views
        where viewer_key is not null
          and created_at <= v_now
        group by viewer_key
        having count(distinct ((created_at at time zone 'Asia/Kolkata')::date)) >= 2
      ) returning_users
    ) else (
      select count(*)
      from (
        select viewer_key
        from public.chapter_views
        where viewer_key is not null
          and created_at >= v_cutoff
          and created_at <= v_now
        group by viewer_key
        having count(distinct ((created_at at time zone 'Asia/Kolkata')::date)) >= 2
      ) returning_users
    ) end,

    'chapter_stats', coalesce((
      select jsonb_agg(to_jsonb(x) order by x.chapter_number nulls last)
      from (
        select
          c.id,
          c.chapter_number,
          c.title,
          c.status,
          coalesce(c.release_date, c.created_at) as "releaseDate",
          (select count(*) from public.chapter_views v where v.chapter_id = c.id) views,
          (select count(*) from public.chapter_likes l where l.chapter_id = c.id)
            + (select count(*) from public.comment_likes cl join public.comments cm on cm.id = cl.comment_id where cm.chapter_id = c.id) likes,
          (select count(*) from public.chapter_shares s where s.chapter_id = c.id) shares,
          (select count(*) from public.chapter_ratings r where r.chapter_id = c.id) rating_count,
          coalesce((select avg(r.rating)::numeric from public.chapter_ratings r where r.chapter_id = c.id), 0) rating_average,

          case when p_days is null then (select count(*) from public.chapter_views v where v.chapter_id = c.id)
            else (select count(*) from public.chapter_views v where v.chapter_id = c.id and v.created_at >= v_cutoff and v.created_at <= v_now)
          end period_views,

          case when p_days is null then (select count(*) from public.chapter_likes l where l.chapter_id = c.id)
              + (select count(*) from public.comment_likes cl join public.comments cm on cm.id = cl.comment_id where cm.chapter_id = c.id)
            else (select count(*) from public.chapter_likes l where l.chapter_id = c.id and l.created_at >= v_cutoff and l.created_at <= v_now)
              + (select count(*) from public.comment_likes cl join public.comments cm on cm.id = cl.comment_id where cm.chapter_id = c.id and cl.created_at >= v_cutoff and cl.created_at <= v_now)
          end period_likes,

          case when p_days is null then (select count(*) from public.chapter_shares s where s.chapter_id = c.id)
            else (select count(*) from public.chapter_shares s where s.chapter_id = c.id and s.created_at >= v_cutoff and s.created_at <= v_now)
          end period_shares,

          case when p_days is null then (select count(*) from public.chapter_ratings r where r.chapter_id = c.id)
            else (select count(*) from public.chapter_ratings r where r.chapter_id = c.id and r.created_at >= v_cutoff and r.created_at <= v_now)
          end period_rating_count,

          (select count(*) from public.chapter_pages p where p.chapter_id = c.id) pages
        from public.chapters c
        where lower(coalesce(c.status,'')) = 'published'
          and c.deleted_at is null
      ) x
    ), '[]'::jsonb)
  ) into v_result;

  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.get_admin_analytics_for_user(p_user_id uuid, p_days integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if p_user_id is null then
    raise exception 'Admin user is required';
  end if;
  perform set_config('request.jwt.claim.sub', p_user_id::text, true);
  return public.get_admin_analytics(p_days);
end;
$function$

