CREATE OR REPLACE FUNCTION public.get_admin_user_stats()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  result jsonb;
begin
  if not exists (select 1 from public.admins where user_id = auth.uid()) then
    raise exception 'Admin access required';
  end if;
  select jsonb_build_object(
    'logged_in_users', (select count(*) from auth.users),
    'notification_users', (select count(distinct user_id) from public.push_subscriptions where user_id is not null),
    'notification_subscriptions', (select count(*) from public.push_subscriptions),
    'new_users_today', (select count(*) from auth.users where created_at >= date_trunc('day', now()))
  ) into result;
  return result;
end;
$function$

CREATE OR REPLACE FUNCTION public.lock_profile_display_name()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if old.display_name_locked then
    new.display_name := old.display_name;
    new.display_name_locked := true;
  elsif new.display_name is distinct from old.display_name then
    new.display_name_locked := true;
  else
    new.display_name_locked := old.display_name_locked;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.lock_profile_public_badge()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF current_setting('app.allow_public_badge_write', true) = 'on' THEN
      RETURN NEW;
    END IF;
    NEW.public_badge := OLD.public_badge;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.lock_profile_public_badge_on_insert()
 RETURNS trigger
