 SET search_path TO 'public'
AS $function$
BEGIN
  IF current_setting('app.allow_public_badge_write', true) = 'on' THEN
    RETURN NEW;
  END IF;
  NEW.public_badge := NULL;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.pdlpl_append_chapter_pages(p_chapter_id uuid, p_pages jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  page jsonb;
  next_page bigint;
begin
  if not private.is_admin() then
    raise exception 'Admin access required';
  end if;

  if p_chapter_id is null then
    raise exception 'Chapter ID is required';
  end if;

  if jsonb_typeof(p_pages) <> 'array' or jsonb_array_length(p_pages) = 0 then
    raise exception 'At least one page is required';
  end if;

  if not exists (
    select 1
    from public.pal_do_pal_ke_lamhe_chapters
    where id = p_chapter_id
  ) then
    raise exception 'Chapter not found';
  end if;

  perform 1
  from public.pal_do_pal_ke_lamhe_chapters
  where id = p_chapter_id
  for update;

  if exists (
    select 1
    from jsonb_array_elements(p_pages) item
    where nullif(trim(item->>'image_path'), '') is null
  ) then
    raise exception 'Every added page needs a valid image path';
  end if;

  select coalesce(max(page_number), 0)
  into next_page
  from public.pal_do_pal_ke_lamhe_chapter_pages
  where chapter_id = p_chapter_id;

  for page in select value from jsonb_array_elements(p_pages)
  loop
    next_page := next_page + 1;

    insert into public.pal_do_pal_ke_lamhe_chapter_pages (
      chapter_id,
      page_number,
      image_path
    )
    values (
      p_chapter_id,
      next_page,
      trim(page->>'image_path')
    );
  end loop;
end;
$function$

CREATE OR REPLACE FUNCTION public.pdlpl_delete_chapter_page(p_page_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_chapter_id uuid;
  v_page_count bigint;
  v_temporary_base bigint;
begin
  if not private.is_admin() then
    raise exception 'Admin access required';
  end if;

  if p_page_id is null then
    raise exception 'Page ID is required';
  end if;

  select page.chapter_id
  into v_chapter_id
  from public.pal_do_pal_ke_lamhe_chapter_pages as page
  where page.id = p_page_id;

  if v_chapter_id is null then
    raise exception 'Page not found';
  end if;

  perform 1
  from public.pal_do_pal_ke_lamhe_chapter_pages as page
  where page.chapter_id = v_chapter_id
  order by page.page_number, page.id
  for update;

  delete from public.pal_do_pal_ke_lamhe_chapter_pages
  where id = p_page_id;

  select count(*)
  into v_page_count
  from public.pal_do_pal_ke_lamhe_chapter_pages as page
  where page.chapter_id = v_chapter_id;

  if v_page_count = 0 then
    return;
  end if;

  select coalesce(max(page.page_number), 0) + v_page_count + 1
  into v_temporary_base
  from public.pal_do_pal_ke_lamhe_chapter_pages as page
  where page.chapter_id = v_chapter_id;

  with renumbered as (
    select
      page.id,
      row_number() over (order by page.page_number, page.id)::bigint as new_number
    from public.pal_do_pal_ke_lamhe_chapter_pages as page
    where page.chapter_id = v_chapter_id
  )
  update public.pal_do_pal_ke_lamhe_chapter_pages as page
  set page_number = v_temporary_base + renumbered.new_number
  from renumbered
  where page.id = renumbered.id;

  with renumbered as (
    select
      page.id,
      row_number() over (order by page.page_number, page.id)::bigint as new_number
    from public.pal_do_pal_ke_lamhe_chapter_pages as page
    where page.chapter_id = v_chapter_id
  )
  update public.pal_do_pal_ke_lamhe_chapter_pages as page
  set page_number = renumbered.new_number
  from renumbered
  where page.id = renumbered.id;
end;
$function$

