CREATE OR REPLACE FUNCTION public.pdlpl_replace_chapter_pages(p_chapter_id uuid, p_pages jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  page jsonb;
  page_count integer;
begin
  if not private.is_admin() then
    raise exception 'Admin access required';
  end if;

  if p_chapter_id is null then
    raise exception 'Chapter ID is required';
  end if;

  if jsonb_typeof(p_pages) <> 'array' or jsonb_array_length(p_pages) = 0 then
    raise exception 'At least one page is required';
  end if;

  if not exists (
    select 1
    from public.pal_do_pal_ke_lamhe_chapters
    where id = p_chapter_id
  ) then
    raise exception 'Chapter not found';
  end if;

  select count(*)
  into page_count
  from jsonb_array_elements(p_pages) item
  where nullif(trim(item->>'image_path'), '') is not null;

  if page_count <> jsonb_array_length(p_pages) then
    raise exception 'Every page needs a valid image path';
  end if;

  if exists (
    select 1
    from (
      select (item->>'page_number')::bigint as page_number
      from jsonb_array_elements(p_pages) item
    ) numbers
    group by page_number
    having count(*) > 1
  ) then
    raise exception 'Page numbers must be unique';
  end if;

  for page in select value from jsonb_array_elements(p_pages)
  loop
    if (page->>'page_number') is null
       or (page->>'page_number')::bigint < 1
       or nullif(trim(page->>'image_path'), '') is null then
      raise exception 'Every page needs a valid page number and image path';
    end if;
  end loop;

  delete from public.pal_do_pal_ke_lamhe_chapter_pages
  where chapter_id = p_chapter_id;

  for page in select value from jsonb_array_elements(p_pages)
  loop
    insert into public.pal_do_pal_ke_lamhe_chapter_pages (
      chapter_id,
      page_number,
      image_path
    )
    values (
      p_chapter_id,
      (page->>'page_number')::bigint,
      trim(page->>'image_path')
    );
  end loop;
end;
$function$

CREATE OR REPLACE FUNCTION public.pdlpl_set_chapter_status(p_chapter_id uuid, p_status text, p_release_date timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS TABLE(id uuid, status text, release_date timestamp with time zone)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_status text;
  v_release_date timestamptz;
begin
  if not private.is_admin() then
    raise exception 'Admin access required';
  end if;

  if p_chapter_id is null then
    raise exception 'Chapter ID is required';
  end if;

  v_status := lower(trim(coalesce(p_status, '')));
  v_status := case v_status
    when 'draft' then 'Draft'
    when 'published' then 'Published'
    when 'archived' then 'Archived'
    when 'scheduled' then 'Scheduled'
    when 'pre-uploaded' then 'Pre-uploaded'
    else null
  end;

  if v_status is null then
    raise exception 'Invalid chapter status';
  end if;

  if not exists (
    select 1
    from public.pal_do_pal_ke_lamhe_chapters as existing_chapter
    where existing_chapter.id = p_chapter_id
  ) then
    raise exception 'Chapter not found';
  end if;

  if v_status = 'Published'
     and not exists (
       select 1
       from public.pal_do_pal_ke_lamhe_chapter_pages as page
       where page.chapter_id = p_chapter_id
     )
  then
    raise exception 'Cannot publish a chapter without manga pages';
  end if;

  select coalesce(
    p_release_date,
    case when v_status = 'Published' then chapter.release_date end,
    case when v_status = 'Published' then now() end
  )
  into v_release_date
  from public.pal_do_pal_ke_lamhe_chapters as chapter
  where chapter.id = p_chapter_id;

  update public.pal_do_pal_ke_lamhe_chapters as chapter
  set
    status = v_status,
    release_date = case
      when v_status = 'Published' then v_release_date
      when p_release_date is not null then p_release_date
      else chapter.release_date
    end
  where chapter.id = p_chapter_id;

  return query
  select chapter.id, chapter.status, chapter.release_date
  from public.pal_do_pal_ke_lamhe_chapters as chapter
  where chapter.id = p_chapter_id;
end;
$function$

