CREATE OR REPLACE FUNCTION public.pdlpl_upsert_chapter(p_chapter_id uuid, p_chapter_number bigint, p_language text, p_title text, p_description text DEFAULT ''::text, p_status text DEFAULT 'Draft'::text, p_release_date timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS TABLE(id uuid, chapter_number bigint, language text, title text, description text, status text, release_date timestamp with time zone, cover_path text)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  normalized_language text := lower(trim(coalesce(p_language, 'hi')));
  normalized_status text := initcap(lower(trim(coalesce(p_status, 'Draft'))));
  chapter_id_value uuid := p_chapter_id;
begin
  if not private.is_admin() then
    raise exception 'Admin access required.';
  end if;

  if chapter_id_value is null then
    chapter_id_value := gen_random_uuid();
  end if;

  if normalized_language not in ('hi', 'en') then
    raise exception 'Unsupported PDPKL language.';
  end if;

  if p_chapter_number is not null and p_chapter_number < 1 then
    raise exception 'Chapter number must be at least 1.';
  end if;

  if trim(coalesce(p_title, '')) = '' then
    raise exception 'Chapter title is required.';
  end if;

  if normalized_status not in ('Draft', 'Published', 'Archived', 'Scheduled', 'Pre-uploaded') then
    raise exception 'Invalid PDPKL chapter status.';
  end if;

  if normalized_status = 'Scheduled' and p_release_date is null then
    raise exception 'Scheduled chapters need a release date.';
  end if;

  if exists (
    select 1
    from public.pal_do_pal_ke_lamhe_chapters as existing_chapter
    where existing_chapter.id = chapter_id_value
  ) then
    update public.pal_do_pal_ke_lamhe_chapters as c
    set
      chapter_number = p_chapter_number,
      language = normalized_language,
      title = trim(p_title),
      description = coalesce(p_description, ''),
      status = normalized_status,
      release_date = p_release_date,
      updated_at = now()
    where c.id = chapter_id_value;
  else
    insert into public.pal_do_pal_ke_lamhe_chapters (
      id, chapter_number, language, title, description, status, release_date
    )
    values (
      chapter_id_value,
      p_chapter_number,
      normalized_language,
      trim(p_title),
      coalesce(p_description, ''),
      normalized_status,
      p_release_date
    );
  end if;

  return query
  select
    c.id,
    c.chapter_number,
    c.language,
    c.title,
    c.description,
    c.status,
    c.release_date,
    c.cover_path
  from public.pal_do_pal_ke_lamhe_chapters as c
  where c.id = chapter_id_value;
end;
$function$

CREATE OR REPLACE FUNCTION public.record_feature_login()
 RETURNS feature_unlock_config
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_inserted integer := 0;
  v_config public.feature_unlock_config;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  INSERT INTO public.feature_login_users (user_id)
  VALUES (v_user_id)
  ON CONFLICT (user_id) DO NOTHING;

  GET DIAGNOSTICS v_inserted = ROW_COUNT;

  IF v_inserted > 0 THEN
    UPDATE public.feature_unlock_config
    SET login_user_count = login_user_count + 1,
        membership_unlocked = membership_unlocked OR login_user_count + 1 >= 200,
        group_chat_unlocked = group_chat_unlocked OR login_user_count + 1 >= 500,
        updated_at = now()
    WHERE id = true;
  END IF;

  SELECT * INTO v_config FROM public.feature_unlock_config WHERE id = true;
  RETURN v_config;
END;
$function$

CREATE OR REPLACE FUNCTION public.record_password_login_failure(p_user_id uuid)
 RETURNS TABLE(failed_count integer, locked_until timestamp with time zone, should_alert boolean, mfa_enabled boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
declare
  v_now timestamptz := now();
  v_failed_count integer := 0;
  v_first_failed_at timestamptz;
  v_last_failed_at timestamptz;
  v_locked_until timestamptz;
  v_previous_count integer := 0;
  v_new_count integer;
  v_mfa_enabled boolean;
begin
  select exists (
    select 1
    from auth.mfa_factors as f
    where f.user_id = p_user_id
      and f.status = 'verified'
  )
  into v_mfa_enabled;

  insert into public.login_password_protection (user_id)
  values (p_user_id)
  on conflict (user_id) do nothing;

  select
    lp.failed_count,
    lp.first_failed_at,
    lp.last_failed_at,
    lp.locked_until
  into
    v_failed_count,
    v_first_failed_at,
    v_last_failed_at,
    v_locked_until
  from public.login_password_protection as lp
  where lp.user_id = p_user_id
  for update;

  if v_locked_until is not null and v_locked_until > v_now then
    return query select v_failed_count, v_locked_until, false, v_mfa_enabled;
    return;
  end if;

  if v_last_failed_at is not null
     and v_last_failed_at < v_now - interval '24 hours' then
    v_failed_count := 0;
    v_first_failed_at := null;
    v_last_failed_at := null;
    v_locked_until := null;
    v_previous_count := 0;
  else
    v_previous_count := v_failed_count;
  end if;

  v_new_count := least(v_previous_count + 1, 5);

  update public.login_password_protection as lp
  set failed_count = v_new_count,
      first_failed_at = coalesce(v_first_failed_at, v_now),
      last_failed_at = v_now,
      locked_until = case
        when v_new_count >= 5 then v_now + interval '24 hours'
        else null
      end,
      last_alerted_at = case
        when v_new_count >= 5 then v_now
        else lp.last_alerted_at
      end
  where lp.user_id = p_user_id
  returning lp.failed_count, lp.locked_until
  into v_failed_count, v_locked_until;

  return query
  select
    v_failed_count,
    v_locked_until,
    v_new_count = 5 and v_previous_count < 5,
    v_mfa_enabled;
end;
$function$

CREATE OR REPLACE FUNCTION public.reorder_chapter_page(p_page_id uuid, p_direction integer)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_chapter_id uuid;
  v_current_number bigint;
  v_target_id uuid;
  v_target_number bigint;
  v_temporary_number bigint;
begin
  if not private.is_admin() then
    raise exception 'Admin access required';
  end if;
  if p_page_id is null then
    raise exception 'Page ID is required';
  end if;
  if p_direction not in (-1, 1) then
    raise exception 'Direction must be -1 or 1';
  end if;

  select page.chapter_id, page.page_number
  into v_chapter_id, v_current_number
  from public.chapter_pages page
  where page.id = p_page_id;

  if v_chapter_id is null then
    raise exception 'Page not found';
  end if;

  perform 1
  from public.chapter_pages page
  where page.chapter_id = v_chapter_id
  order by page.page_number, page.id
  for update;

  if p_direction = -1 then
    select page.id, page.page_number
    into v_target_id, v_target_number
    from public.chapter_pages page
    where page.chapter_id = v_chapter_id
      and (page.page_number, page.id) < (v_current_number, p_page_id)
    order by page.page_number desc, page.id desc
    limit 1;
  else
    select page.id, page.page_number
    into v_target_id, v_target_number
    from public.chapter_pages page
    where page.chapter_id = v_chapter_id
      and (page.page_number, page.id) > (v_current_number, p_page_id)
    order by page.page_number asc, page.id asc
    limit 1;
  end if;

  if v_target_id is null then
    return;
  end if;

  select coalesce(max(page.page_number), 0) + 1
  into v_temporary_number
  from public.chapter_pages page
  where page.chapter_id = v_chapter_id;

  update public.chapter_pages
  set page_number = v_temporary_number
  where id = p_page_id;

  update public.chapter_pages
  set page_number = v_current_number
  where id = v_target_id;

  update public.chapter_pages
  set page_number = v_target_number
  where id = p_page_id;
end;
$function$

